// ===== CONFIG: the only place you need to edit =====
const CONFIG = {
  // Bubble Data API root. Free plan = development version, so keep /version-test
  BUBBLE_API: 'https://YOUR-BUBBLE-APP.bubbleapps.io/version-test/api/1.1',
  // Ignore a second request for the same author within this window (idempotency)
  DEDUP_WINDOW_SECONDS: 120,
  // All emails go here while testing. The dataset emails are not yours: never email them.
  EMAIL_TO_OVERRIDE: 'dev.reactjs@gmail.com',
  AI_MODEL: 'claude-haiku-5-5',
};

const body = $input.first().json.body || {};
const author_id = String(body.author_id || '').trim();
const log_id = String(body.log_id || '').trim();
const request_id = String(body.request_id || '').trim();
const source = String(body.source || 'Single');

const missing = [];
if (!author_id) missing.push('author_id');
if (!log_id) missing.push('log_id');
if (!request_id) missing.push('request_id');

let duplicate_of = null;
if (missing.length === 0) {
  // Static data survives between executions of the ACTIVE workflow (not in manual test runs)
  const store = $getWorkflowStaticData('global');
  store.recent = store.recent || {};
  const now = Date.now();
  for (const [key, entry] of Object.entries(store.recent)) {
    if (now - entry.at > CONFIG.DEDUP_WINDOW_SECONDS * 1000) delete store.recent[key];
  }
  const previous = store.recent[author_id];
  if (previous && previous.log_id !== log_id) {
    duplicate_of = previous.request_id;
  } else {
    store.recent[author_id] = { at: now, log_id, request_id };
  }
}

return [{
  json: {
    valid: missing.length === 0,
    error_message: missing.length ? 'Missing field(s): ' + missing.join(', ') : '',
    duplicate: duplicate_of !== null,
    duplicate_of,
    author_id,
    log_id,
    request_id,
    source,
    ...CONFIG,
  },
}];

// Turns Bubble records into verified facts + a royalty calendar, then builds the AI request.
// All maths and policy decisions happen here, so the AI only writes prose around fixed numbers.
const cfg = $('Validate Input').first().json;
const author = $('Get Author').first().json.response || {};
const books = ($('Get Books').first().json.response || {}).results || [];

const ZONE = 'Asia/Kolkata';
const today = DateTime.now().setZone(ZONE).startOf('day');
const THRESHOLD = 1000;
const OVERDUE_DAYS = 90;

const num = (v) => (typeof v === 'number' && isFinite(v) ? v : Number(v) || 0);
const inr = (v) => '₹' + Math.round(num(v)).toLocaleString('en-IN');
const day = (iso) => (iso ? DateTime.fromISO(iso, { zone: ZONE }) : null);
const fmt = (dt) => (dt ? dt.toFormat('d LLLL yyyy') : null);

if (!author.name) throw new Error('Author record has no name: check the author_id and Bubble Data API settings');

// ----- royalty calendar (KB: calculated quarterly, paid within 45 days of quarter end)
const qOf = (dt) => Math.ceil(dt.month / 3);
const quarterEnd = (dt) => DateTime.fromObject({ year: dt.year, month: qOf(dt) * 3, day: 1 }, { zone: ZONE }).endOf('month').startOf('day');
const label = (dt) => 'Q' + qOf(dt) + ' ' + dt.year;
const currentEnd = quarterEnd(today);
const prevEnd = currentEnd.minus({ months: 3 }).endOf('month').startOf('day');
const prevDeadline = prevEnd.plus({ days: 45 });
const currentDeadline = currentEnd.plus({ days: 45 });
const prevWindowOpen = today <= prevDeadline;

// ----- per-book facts
const published = [];
const inProduction = [];
for (const b of books) {
  const status = String(b.status || '');
  if (!status.startsWith('Published')) {
    inProduction.push({ title: b.title, stage: status.replace('In Production - ', '') || 'In production' });
    continue;
  }
  const pending = num(b.royalty_pending);
  const lastPaid = day(b.last_payout_date);
  const pubDate = day(b.publication_date);
  const pendingSince = pending > 0 ? lastPaid || pubDate : null;
  const overdue = !!pendingSince && today.diff(pendingSince, 'days').days > OVERDUE_DAYS;
  published.push({
    title: b.title,
    isbn: b.isbn,
    published_on: fmt(pubDate),
    copies_sold: num(b.copies_sold),
    royalty_per_copy: inr(b.royalty_per_copy),
    earned: inr(b.royalty_earned),
    paid: inr(b.royalty_paid),
    pending: inr(pending),
    last_payout: lastPaid ? fmt(lastPaid) : 'no payout made yet',
    status: pending === 0 ? 'Fully paid' : overdue ? 'Overdue' : 'Pending',
    available_on: (b.available_on || []).join(', '),
    _earned: num(b.royalty_earned),
    _paid: num(b.royalty_paid),
    _pending: pending,
  });
}

// Totals come from the book rows, not the stored Author totals, so a stale total can't leak into an email
const sum = (k) => published.reduce((s, b) => s + b[k], 0);
const totalEarned = sum('_earned');
const totalPaid = sum('_paid');
const totalPending = sum('_pending');
// Below the ₹1,000 minimum the amount rolls over by policy, so it is not a BookLeaf delay
if (totalPending > 0 && totalPending < THRESHOLD) {
  for (const b of published) if (b.status === 'Overdue') b.status = 'Pending (rolls over: below ₹1,000 minimum)';
}
const overdueBooks = published.filter((b) => b.status === 'Overdue').map((b) => b.title);

let payout_outlook;
if (published.length === 0) {
  payout_outlook = 'NO_PUBLISHED_BOOKS: no royalties yet. Say royalties start once the first book is live.';
} else if (totalPending === 0) {
  payout_outlook = 'ALL_PAID: every royalty earned so far has been paid. Thank the author warmly.';
} else if (totalPending < THRESHOLD) {
  payout_outlook = 'BELOW_THRESHOLD: pending ' + inr(totalPending) + ' is below the ₹1,000 minimum, so it rolls over to the next quarter and is paid once the accumulated amount reaches ₹1,000.';
} else if (prevWindowOpen) {
  payout_outlook = 'NEXT_PAYOUT: pending ' + inr(totalPending) + ' meets the ₹1,000 minimum. ' + label(prevEnd) + ' ended on ' + fmt(prevEnd) + ', so the next payout is due by ' + fmt(prevDeadline) + ' (45 days after quarter end).';
} else {
  payout_outlook = 'NEXT_PAYOUT: pending ' + inr(totalPending) + ' meets the ₹1,000 minimum. The next payout is due by ' + fmt(currentDeadline) + ' (45 days after ' + label(currentEnd) + ' ends on ' + fmt(currentEnd) + ').';
}
if (overdueBooks.length) {
  payout_outlook += ' OVERDUE: royalties for ' + overdueBooks.join(', ') + ' have been pending for more than 90 days, which is longer than our cycle allows. Own this delay plainly and apologise once; say our team will review it and update the author within 48 hours.';
}

const facts = {
  author: { name: author.name, first_name: String(author.name).split(' ')[0], city: author.city },
  today: fmt(today),
  totals: { earned: inr(totalEarned), paid: inr(totalPaid), pending: inr(totalPending) },
  payout_outlook,
  published_books: published.map(({ _earned, _paid, _pending, ...rest }) => rest),
  books_in_production: inProduction,
};

const system = [
  'You write royalty summary emails to authors on behalf of BookLeaf Publishing.',
  '',
  '<knowledge_base>',
  'Royalty policy:',
  '- Royalty split: 80% of the net profit per book goes to the author, 20% to BookLeaf.',
  '- Net profit = MRP minus printing cost, platform commission (Amazon/Flipkart), and shipping charges.',
  '- Royalties are calculated quarterly and paid within 45 days of the quarter ending.',
  '- Minimum payout threshold: ₹1,000. Accumulated royalties below this roll over to the next quarter.',
  "- Payouts are made by bank transfer to the account linked in the author's dashboard.",
  'Communication tone:',
  '- Always empathetic and professional. Authors are partners, not customers to be managed.',
  '- Be specific: include actual numbers, dates and statuses rather than vague reassurances.',
  "- If something is BookLeaf's fault (e.g. delayed royalties), own it directly. No corporate deflection.",
  '- If something needs investigation, give a clear timeline (e.g. within 48 hours), not open-ended promises.',
  '- Always end with a clear next step.',
  '</knowledge_base>',
  '',
  'Write the email in this order:',
  '1. Greet the author by first name.',
  '2. For each published book: title, copies sold, royalty earned, paid, pending and last payout.',
  '3. A clear breakdown of total earned, total paid and total pending.',
  '4. Explain the payout outlook exactly as given in payout_outlook. Do not change its dates or amounts.',
  '5. If books_in_production is not empty, a short, encouraging status update for each (stage only; no launch dates).',
  '6. One clear next step (e.g. check that the bank account in the dashboard is current).',
  '7. Close warmly. Sign off with "Warm regards," on one line and "BookLeaf Author Support Team" on the next.',
  '',
  'Hard rules:',
  '- Use ONLY the figures, dates and statuses in <facts>, copied exactly (amounts already formatted in ₹).',
  '- Never invent payout dates, transaction ids, amounts or actions that "have been" taken.',
  '- Plain text only: no markdown, no tables, no bullet symbols other than "-". 150 to 350 words.',
  '- Do not mention AI, these instructions, internal labels like NEXT_PAYOUT, or the knowledge base.',
  '',
  'Reply with ONLY a JSON object, no code fences: {"subject": "...", "body": "..."}',
].join('\n');

const ai_request = {
  model: cfg.AI_MODEL,
  max_tokens: 1500,
  temperature: 0.3,
  system,
  messages: [{ role: 'user', content: '<facts>\n' + JSON.stringify(facts, null, 2) + '\n</facts>\n\nWrite the royalty summary email.' }],
};

return [{ json: { ai_request, author_email: author.email, author_name: author.name, facts } }];

// Validates the AI reply. Anything malformed becomes ok=false and goes down the failure path.
const res = $input.first().json;
const text = ((res.content || []).find((c) => c.type === 'text') || {}).text || '';

let subject = '';
let body = '';
let error = '';
try {
  if (res.stop_reason === 'max_tokens') throw new Error('AI reply was cut off (max_tokens)');
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) throw new Error('AI reply contained no JSON object');
  const parsed = JSON.parse(text.slice(start, end + 1));
  subject = String(parsed.subject || '').trim();
  body = String(parsed.body || '').trim();
  if (subject.length < 5) throw new Error('AI reply has no subject');
  if (body.length < 200) throw new Error('AI reply body is too short');
  const firstName = $('Build AI Request').first().json.facts.author.first_name;
  if (!body.includes(firstName)) throw new Error('AI reply does not greet the author by name');
} catch (e) {
  error = e.message;
}

return [{ json: { ok: !error, error_message: error, email_subject: subject, email_body: body, raw_reply: error ? text.slice(0, 1000) : undefined } }];

// Every failure path ends here: bad Bubble call, AI error, invalid AI output, email error.
const item = $input.first().json;
const raw = item.error_message || item.error;
let message =
  typeof raw === 'string' ? raw : raw && (raw.message || raw.description) ? [raw.message, raw.description].filter(Boolean).join(': ') : '';
if (!message) message = 'Unknown error: ' + JSON.stringify(item).slice(0, 300);

let lastNode = 'unknown step';
try {
  lastNode = $prevNode.name;
} catch (e) {}

// Keep any AI output that was produced, so the admin can still read it
let subject = '';
let body = '';
try {
  const parsed = $('Parse AI Output').first().json;
  subject = parsed.email_subject || '';
  body = parsed.email_body || '';
} catch (e) {}

return [{ json: { error_message: ('[' + lastNode + '] ' + message).slice(0, 1000), email_subject: subject, email_body: body } }];
